export type Block =
  | { type: "h2"; text: string }
  | { type: "h3"; text: string }
  | { type: "p"; text: string }
  | { type: "ul"; items: string[] }
  | { type: "ol"; items: string[] }
  | { type: "callout"; title: string; text: string }
  | { type: "quote"; text: string; attribution: string }
  | { type: "table"; caption: string; headers: string[]; rows: string[][] }
  | { type: "faq"; items: { q: string; a: string }[] };

export type PostCategory = "Academy" | "News" | "Reviews";

// Article = default long-form guide. HowTo/FAQPage/Review add matching JSON-LD
// alongside Article in the page's @graph. See app/blog/[slug]/page.tsx.
export type SchemaType = "Article" | "HowTo" | "FAQPage" | "Review";

export interface FeaturedImage {
  src: string; // /images/blog/<slug>.jpg — see public/images/blog
  alt: string; // descriptive, includes the primary keyword
  credit: string; // "Photo by <name> on Pexels" / "... on Unsplash"
  creditUrl: string;
}

export interface ReviewMeta {
  itemName: string;
  itemType: "SoftwareApplication" | "Product" | "Service";
  ratingValue: number; // 1-5
  bestRating?: number; // defaults to 5
}

export interface Post {
  slug: string;
  title: string;
  description: string;
  keyword: string;
  supportingKeywords?: string[];
  longTailPhrases?: string[];
  category?: PostCategory;
  date: string;
  readMins: number;
  author?: string; // defaults to "PerDiemWise Content Team" in the page template
  schemaType?: SchemaType;
  review?: ReviewMeta; // required when schemaType === "Review"
  featuredImage?: FeaturedImage;
  body: Block[];
}

